-- Rollback of 154_drop_grafana_panel_views.sql. It is NOT part of the chain (the migrator reads sql/ only); an operator
-- runs it by hand. No build reads either view, so no image has to roll back first. It re-creates the two views with the
-- definitions of the head baseline (baseline/head.json), then removes the version row last: with it left in
-- schema_migrations, a later `dho migrate clickhouse upgrade` reads 154 as applied and never drops the views again.
CREATE VIEW IF NOT EXISTS v_file_hotspots_windowed (`repo_id` UUID, `file_path` String, `churn_loc_window` UInt64, `cyclomatic_total` UInt32, `ownership_concentration` Nullable(Float64), `incident_count` UInt8, `churn_signal` Float64, `complexity_signal` Float64, `ownership_signal` Float64, `incident_signal` Float64, `risk_score` Float64) AS WITH toDate(now()) - toIntervalDay(30) AS start_day, toDate(now()) AS end_day SELECT metrics.repo_id AS repo_id, metrics.path AS file_path, sumIf(metrics.churn, (metrics.day >= start_day) AND (metrics.day < end_day)) AS churn_loc_window, lookup.cyclomatic_total AS cyclomatic_total, lookup.ownership_concentration AS ownership_concentration, 0 AS incident_count, log1p(churn_loc_window) AS churn_signal, log1p(coalesce(cyclomatic_total, 0)) AS complexity_signal, coalesce(ownership_concentration, 0) AS ownership_signal, log1p(incident_count) AS incident_signal, (((0.5 * churn_signal) + (0.3 * complexity_signal)) + (0.2 * ownership_signal)) AS risk_score FROM (SELECT * FROM file_metrics_daily ORDER BY computed_at DESC LIMIT 1 BY org_id, repo_id, day, path) AS metrics LEFT JOIN (SELECT repo_id, file_path, argMax(cyclomatic_total, computed_at) AS cyclomatic_total, argMax(blame_concentration, computed_at) AS ownership_concentration FROM file_hotspot_daily GROUP BY repo_id, file_path) AS lookup ON (lookup.repo_id = metrics.repo_id) AND (lookup.file_path = metrics.path) WHERE (metrics.day >= start_day) AND (metrics.day < end_day) GROUP BY metrics.repo_id, metrics.path, lookup.cyclomatic_total, lookup.ownership_concentration;
CREATE VIEW IF NOT EXISTS v_ic_landscape_points (`as_of_day` Date, `map_name` LowCardinality(String), `team_id` LowCardinality(String), `identity_id` String, `x_raw` Float64, `y_raw` Float64, `x_norm` Float64, `y_norm` Float64) AS SELECT as_of_day, map_name, team_id, identity_id, x_raw, y_raw, x_norm, y_norm FROM ic_landscape_rolling_30d;
ALTER TABLE schema_migrations DELETE WHERE version = '154_drop_grafana_panel_views.sql' SETTINGS mutations_sync = 2;
